    size_t i = hash(key) % t->cap;
    while (t->slots[i].state != 0) {
        if (t->slots[i].state == 1 && strcmp(t->slots[i].key, key) == 0) {
            *out = t->slots[i].value;
            return 1;
        }
        i = (i + 1) % t->cap;
    }
    return 0;
}

